package com.suncanvas.app.widget.render

import com.suncanvas.app.R
import com.suncanvas.app.widget.model.FontWeightChoice
import com.suncanvas.app.widget.model.WidgetFont

/** Generated by tools/gen_font_resources.py — maps widget fonts to bundled font files and live-clock layouts. */
object FontResources {
    fun fontRes(font: WidgetFont, weight: FontWeightChoice): Int = when (font) {
        WidgetFont.INTER -> when (weight) { FontWeightChoice.LIGHT -> R.font.inter_300; FontWeightChoice.REGULAR -> R.font.inter_400; FontWeightChoice.BOLD -> R.font.inter_700 }
        WidgetFont.NUNITO -> when (weight) { FontWeightChoice.LIGHT -> R.font.nunito_300; FontWeightChoice.REGULAR -> R.font.nunito_400; FontWeightChoice.BOLD -> R.font.nunito_800 }
        WidgetFont.POPPINS -> when (weight) { FontWeightChoice.LIGHT -> R.font.poppins_300; FontWeightChoice.REGULAR -> R.font.poppins_400; FontWeightChoice.BOLD -> R.font.poppins_600 }
        WidgetFont.SPACE_GROTESK -> when (weight) { FontWeightChoice.LIGHT -> R.font.space_grotesk_300; FontWeightChoice.REGULAR -> R.font.space_grotesk_400; FontWeightChoice.BOLD -> R.font.space_grotesk_700 }
        WidgetFont.PLAYFAIR -> when (weight) { FontWeightChoice.LIGHT -> R.font.playfair_display_400; FontWeightChoice.REGULAR -> R.font.playfair_display_400; FontWeightChoice.BOLD -> R.font.playfair_display_700 }
        WidgetFont.CORMORANT -> when (weight) { FontWeightChoice.LIGHT -> R.font.cormorant_garamond_300; FontWeightChoice.REGULAR -> R.font.cormorant_garamond_400; FontWeightChoice.BOLD -> R.font.cormorant_garamond_700 }
        WidgetFont.JETBRAINS_MONO -> when (weight) { FontWeightChoice.LIGHT -> R.font.jetbrains_mono_300; FontWeightChoice.REGULAR -> R.font.jetbrains_mono_400; FontWeightChoice.BOLD -> R.font.jetbrains_mono_700 }
        WidgetFont.ORBITRON -> when (weight) { FontWeightChoice.LIGHT -> R.font.orbitron_400; FontWeightChoice.REGULAR -> R.font.orbitron_400; FontWeightChoice.BOLD -> R.font.orbitron_700 }
        WidgetFont.OSWALD -> when (weight) { FontWeightChoice.LIGHT -> R.font.oswald_300; FontWeightChoice.REGULAR -> R.font.oswald_400; FontWeightChoice.BOLD -> R.font.oswald_600 }
        WidgetFont.BEBAS -> when (weight) { FontWeightChoice.LIGHT -> R.font.bebas_neue_400; FontWeightChoice.REGULAR -> R.font.bebas_neue_400; FontWeightChoice.BOLD -> R.font.bebas_neue_400 }
        WidgetFont.QUICKSAND -> when (weight) { FontWeightChoice.LIGHT -> R.font.quicksand_300; FontWeightChoice.REGULAR -> R.font.quicksand_400; FontWeightChoice.BOLD -> R.font.quicksand_700 }
    }

    fun liveLayout(font: WidgetFont, weight: FontWeightChoice): Int = when (font) {
        WidgetFont.INTER -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_inter_300; FontWeightChoice.REGULAR -> R.layout.widget_live_inter_400; FontWeightChoice.BOLD -> R.layout.widget_live_inter_700 }
        WidgetFont.NUNITO -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_nunito_300; FontWeightChoice.REGULAR -> R.layout.widget_live_nunito_400; FontWeightChoice.BOLD -> R.layout.widget_live_nunito_800 }
        WidgetFont.POPPINS -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_poppins_300; FontWeightChoice.REGULAR -> R.layout.widget_live_poppins_400; FontWeightChoice.BOLD -> R.layout.widget_live_poppins_600 }
        WidgetFont.SPACE_GROTESK -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_space_grotesk_300; FontWeightChoice.REGULAR -> R.layout.widget_live_space_grotesk_400; FontWeightChoice.BOLD -> R.layout.widget_live_space_grotesk_700 }
        WidgetFont.PLAYFAIR -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_playfair_display_400; FontWeightChoice.REGULAR -> R.layout.widget_live_playfair_display_400; FontWeightChoice.BOLD -> R.layout.widget_live_playfair_display_700 }
        WidgetFont.CORMORANT -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_cormorant_garamond_300; FontWeightChoice.REGULAR -> R.layout.widget_live_cormorant_garamond_400; FontWeightChoice.BOLD -> R.layout.widget_live_cormorant_garamond_700 }
        WidgetFont.JETBRAINS_MONO -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_jetbrains_mono_300; FontWeightChoice.REGULAR -> R.layout.widget_live_jetbrains_mono_400; FontWeightChoice.BOLD -> R.layout.widget_live_jetbrains_mono_700 }
        WidgetFont.ORBITRON -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_orbitron_400; FontWeightChoice.REGULAR -> R.layout.widget_live_orbitron_400; FontWeightChoice.BOLD -> R.layout.widget_live_orbitron_700 }
        WidgetFont.OSWALD -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_oswald_300; FontWeightChoice.REGULAR -> R.layout.widget_live_oswald_400; FontWeightChoice.BOLD -> R.layout.widget_live_oswald_600 }
        WidgetFont.BEBAS -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_bebas_neue_400; FontWeightChoice.REGULAR -> R.layout.widget_live_bebas_neue_400; FontWeightChoice.BOLD -> R.layout.widget_live_bebas_neue_400 }
        WidgetFont.QUICKSAND -> when (weight) { FontWeightChoice.LIGHT -> R.layout.widget_live_quicksand_300; FontWeightChoice.REGULAR -> R.layout.widget_live_quicksand_400; FontWeightChoice.BOLD -> R.layout.widget_live_quicksand_700 }
    }

}
